(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.008+t*0.15)*20;
  let wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.009-t*0.18)*18;
  let sx = x+wx, sy = y+wy;
  const wx2 = Math.sin(sy*0.025+t*0.4)*12 + Math.cos(sx*0.02-t*0.3)*8;
  const wy2 = Math.cos(sx*0.022+t*0.35)*12 + Math.sin(sy*0.018-t*0.45)*8;
  sx += wx2; sy += wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.45+1)*50, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.13, 1.6, 1.12]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const pulse = 0.7+Math.sin(t*0.8+w*3)*0.3;
    aS+=Math.sin(d*f-t*sp)*pulse;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*pulse;
    aS2+=Math.sin(d*f*1.8-t*sp*1.3+2.0)*pulse*0.5;
    iS2+=Math.sin(d*f*1.2+t*sp*0.9+0.8)*pulse*0.5;
  }
  const act=(aS+aS2*0.4)/8, inh=(iS+iS2*0.4)/8;
  const turb = (sx*0.0123+t*0.37)^0 + (sy*0.0171-t*0.29)^0;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+Math.sin(sy*0.05+t)*2+t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08+ang*2-t*2.5)*0.15;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.15;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+micro)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const laplacian = Math.sin(sx*0.08+sy*0.06+t)*Math.cos(sx*0.06-sy*0.08-t*0.7)*0.2;
  const blend = reaction*0.6+cell*0.2+laplacian*0.2, v=blend*0.5+0.5;
  const pal = [
    [5,12,55],[12,45,95],[18,95,125],[25,155,145],[120,195,120],
    [210,195,65],[225,140,60],[195,75,75],[130,35,65],[65,18,55],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.08:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*60)|0)
  ];
}
